        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 35000000,
                    netDebt: 145000000,
                    annualEbitda: 50400000,
                    quarterlyEbitda: 12600000,
                    debtToEbitda: 2.88,
                    interestCoverage: 4.1,
                    totalScore: 0,
                    earningsScore: 0,
                    covenantScore: 0,
                    cashflowScore: 0,
                    costCapitalScore: 0,
                    communicationScore: 0,
                    covenantHistory: [],
                    coverageHistory: [],
                    scoreHistory: [],
                    cashHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    decisionA: 0,
                    decisionB: 0,
                    decisionC: 0
                };
            }
            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function' && !this._reactBound) {
                // FIX(v1.1.0): the framework's undo restores state but never re-invokes
                // the adapter view; and language changes should re-render the (localized)
                // scenario. Keep the briefing reactive to both.
                this._reactBound = true;
                sim.eventBus.on('period:undone', function(st) { self._updateBriefing(st || sim.state); });
                sim.eventBus.on('language:changed', function() { self._updateBriefing(sim.state); });
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var selA = document.getElementById('decisionAInput');
            var selB = document.getElementById('decisionBInput');
            var selC = document.getElementById('decisionCInput');
            if (selA) decisions.decisionA = parseInt(selA.value);
            if (selB) decisions.decisionB = parseInt(selB.value);
            if (selC) decisions.decisionC = parseInt(selC.value);

            if (!decisions.decisionA || decisions.decisionA < 1 || decisions.decisionA > 4) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_all_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.decisionB || decisions.decisionB < 1 || decisions.decisionB > 4) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_all_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.decisionC || decisions.decisionC < 1 || decisions.decisionC > 4) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_all_warning'), 'warning'
                );
                return false;
            }
            // FIX(v1.1.0): removed a redundant _updateBriefing() here. It rebuilt
            // the selects mid-validation (resetting them to the placeholder), which
            // clobbered the learner's in-progress choice during the framework's
            // competition preview. The next round is rendered by calculateResults.
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var idxA = d.decisionA - 1;
            var idxB = d.decisionB - 1;
            var idxC = d.decisionC - 1;

            var scA = round.decisionA.scores[idxA];
            var scB = round.decisionB.scores[idxB];
            var scC = round.decisionC.scores[idxC];

            var rEarnings = Math.round((scA.earnings + scB.earnings + scC.earnings) / 3 * 10) / 10;
            var rCovenant = Math.round((scA.covenant + scB.covenant + scC.covenant) / 3 * 10) / 10;
            var rCashflow = Math.round((scA.cashflow + scB.cashflow + scC.cashflow) / 3 * 10) / 10;
            var rCostCap = Math.round((scA.costCapital + scB.costCapital + scC.costCapital) / 3 * 10) / 10;
            var rComm = Math.round((scA.communication + scB.communication + scC.communication) / 3 * 10) / 10;

            var roundScore = Math.round(
                rEarnings * 0.25 + rCovenant * 0.25 + rCashflow * 0.20 +
                rCostCap * 0.15 + rComm * 0.15
            );

            var qualityMultiplier = (rEarnings + rCovenant + rCashflow + rCostCap + rComm) / 50;
            var bi = round.baseImpact;
            var ebitdaAdj = bi.ebitdaChange * (1 + (qualityMultiplier - 0.5) * 0.3);
            var debtAdj = bi.debtChange * (1 - (qualityMultiplier - 0.5) * 0.2);
            var cashAdj = bi.cashChange * (1 + (qualityMultiplier - 0.5) * 0.3);
            var covAdj = bi.coverageChange * (1 - (qualityMultiplier - 0.5) * 0.2);

            ds.quarterlyEbitda = Math.round(ds.quarterlyEbitda + ebitdaAdj);
            ds.annualEbitda = ds.quarterlyEbitda * 4;
            ds.netDebt = Math.round(ds.netDebt + debtAdj);
            ds.cash = Math.round(ds.cash + cashAdj);
            ds.debtToEbitda = ds.annualEbitda > 0 ? Math.round(ds.netDebt / ds.annualEbitda * 100) / 100 : 9.99;
            ds.interestCoverage = Math.round((ds.interestCoverage + covAdj) * 100) / 100;
            if (ds.interestCoverage < 1.0) ds.interestCoverage = 1.0;

            ds.earningsScore += rEarnings;
            ds.covenantScore += rCovenant;
            ds.cashflowScore += rCashflow;
            ds.costCapitalScore += rCostCap;
            ds.communicationScore += rComm;
            ds.totalScore += roundScore;

            ds.covenantHistory.push(ds.debtToEbitda);
            ds.coverageHistory.push(ds.interestCoverage);
            ds.scoreHistory.push(roundScore);
            ds.cashHistory.push(ds.cash);

            // platform score: same percent getPerformanceSummary computes at the end, totalScore over rounds played times 10, scaled to 0-100
            var roundsPlayed = state.currentPeriod || 1;
            var overallScore = Math.max(0, Math.min(100, Math.round(ds.totalScore / (roundsPlayed * 10) * 100)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            // FIX(v1.1.0): advance synchronously to the next round. The previous
            // setTimeout closure read state.currentPeriod AFTER the framework had
            // incremented it, so it skipped a round and desynced the shown scenario
            // from the scoring table. Guard on state identity so the deep-cloned
            // competition preview never mutates the live DOM.
            if (window.mySimulation && state === window.mySimulation.state) {
                var nextPeriod = (state.currentPeriod || 1) + 1;
                if (nextPeriod <= this.ROUNDS.length) {
                    this._updateBriefing({ currentPeriod: nextPeriod });
                }
            }

            return {
                period: state.currentPeriod,
                roundTitle: round.title,
                decisionA: d.decisionA,
                decisionB: d.decisionB,
                decisionC: d.decisionC,
                earningsScore: rEarnings,
                covenantScore: rCovenant,
                cashflowScore: rCashflow,
                costCapitalScore: rCostCap,
                communicationScore: rComm,
                roundScore: roundScore,
                debtToEbitda: ds.debtToEbitda,
                interestCoverage: ds.interestCoverage,
                cash: ds.cash,
                totalScore: ds.totalScore
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                (v) => '$' + (v / 1000000).toFixed(1) + 'M');
            uiManager.bind('debtEbitdaDisplay', 'domainState.debtToEbitda',
                (v) => v.toFixed(2) + 'x');
            uiManager.bind('interestCovDisplay', 'domainState.interestCoverage',
                (v) => v.toFixed(1) + 'x');
            uiManager.bind('ebitdaDisplay', 'domainState.quarterlyEbitda',
                (v) => '$' + (v / 1000000).toFixed(1) + 'M');
            uiManager.bind('scoreDisplay', 'domainState.totalScore');
        }

