        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalScore = 0;
            var rounds = history.length;
            for (var i = 0; i < history.length; i++) {
                totalScore += (history[i].results ? history[i].results.roundScore : 0) || 0;
            }
            var avgScore = Math.round(totalScore / rounds * 10) / 10;
            var maxPossible = rounds * 10;
            var pct = Math.round(totalScore / maxPossible * 100);

            var performance = window.mySimulation.t('perf_junior_analyst');
            if (pct >= 85) performance = window.mySimulation.t('perf_expert_cfo');
            else if (pct >= 70) performance = window.mySimulation.t('perf_senior_cfo');
            else if (pct >= 55) performance = window.mySimulation.t('perf_competent_treasurer');
            else if (pct >= 40) performance = window.mySimulation.t('perf_finance_manager');

            var insights = [];
            var lastState = history[history.length - 1];
            var ds = lastState.domainState || {};

            if (ds.debtToEbitda && ds.debtToEbitda > 3.5) {
                insights.push(window.mySimulation.t('insight_covenant_breach'));
            }
            if (ds.communicationScore && ds.communicationScore / rounds > 7) {
                insights.push(window.mySimulation.t('insight_excellent_comm'));
            }
            if (pct >= 70) {
                insights.push(window.mySimulation.t('insight_strong_treasury'));
            } else {
                insights.push(window.mySimulation.t('insight_review_hedging'));
            }

            return {
                totalScore: totalScore,
                maxPossible: maxPossible,
                percentage: pct,
                avgRoundScore: avgScore,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.debtToEbitda > 3.5) {
                return window.mySimulation.t('hint_covenant_breach');
            }
            if (results.debtToEbitda > 3.2) {
                return window.mySimulation.t('hint_covenant_warning');
            }
            if (results.interestCoverage < 3.5) {
                return window.mySimulation.t('hint_coverage_low');
            }
            if (results.roundScore >= 8) {
                return window.mySimulation.t('hint_excellent');
            }
            if (results.roundScore <= 4) {
                return window.mySimulation.t('hint_needs_improvement');
            }
            return null;
        }

