        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var lang = (window.mySimulation && window.mySimulation.lang) || 'en';
            var isEs = lang === 'es';

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = isEs ? round.briefingEs : round.briefing;
            }

            var briefTitle = document.getElementById('briefingTitle');
            if (briefTitle) {
                briefTitle.textContent = isEs ? round.titleEs : round.title;
            }

            var selA = document.getElementById('decisionAInput');
            var selB = document.getElementById('decisionBInput');
            var selC = document.getElementById('decisionCInput');

            var labelA = document.getElementById('labelDecA');
            var labelB = document.getElementById('labelDecB');
            var labelC = document.getElementById('labelDecC');

            if (labelA) labelA.textContent = isEs ? round.decisionA.labelEs : round.decisionA.label;
            if (labelB) labelB.textContent = isEs ? round.decisionB.labelEs : round.decisionB.label;
            if (labelC) labelC.textContent = isEs ? round.decisionC.labelEs : round.decisionC.label;

            var placeholder = isEs ? '-- Seleccione una opción --' : '-- Select an option --';

            if (selA) {
                selA.innerHTML = '<option value="0">' + placeholder + '</option>';
                var opts = isEs ? round.decisionA.optionsEs : round.decisionA.options;
                for (var i = 0; i < opts.length; i++) {
                    selA.innerHTML += '<option value="' + (i + 1) + '">' + String.fromCharCode(65 + i) + ') ' + opts[i] + '</option>';
                }
            }
            if (selB) {
                selB.innerHTML = '<option value="0">' + placeholder + '</option>';
                var optsB = isEs ? round.decisionB.optionsEs : round.decisionB.options;
                for (var j = 0; j < optsB.length; j++) {
                    selB.innerHTML += '<option value="' + (j + 1) + '">' + String.fromCharCode(65 + j) + ') ' + optsB[j] + '</option>';
                }
            }
            if (selC) {
                selC.innerHTML = '<option value="0">' + placeholder + '</option>';
                var optsC = isEs ? round.decisionC.optionsEs : round.decisionC.options;
                for (var k = 0; k < optsC.length; k++) {
                    selC.innerHTML += '<option value="' + (k + 1) + '">' + String.fromCharCode(65 + k) + ') ' + optsC[k] + '</option>';
                }
            }
        }
